package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"runtime/debug"
)

// --- 自定义错误类型，实现 Unwrap 参与错误链 ---

type BizError struct {
	Code  string // 业务错误码，如 USER_NOT_FOUND
	HTTP  int    // 映射 HTTP 状态码
	Retry bool   // 调用方是否可重试
	Cause error  // 原始错误，参与 Unwrap 链
}

func (e *BizError) Error() string { return fmt.Sprintf("%s: %v", e.Code, e.Cause) }
func (e *BizError) Unwrap() error { return e.Cause }

// --- sentinel error ---

var ErrUserNotFound = errors.New("user not found")

// --- 底层函数：用 %w 保留根因 ---

func loadUser(ctx context.Context, id int) error {
	if id <= 0 {
		return fmt.Errorf("loadUser id=%d: %w", id, ErrUserNotFound)
	}
	// 模拟上游超时：标准库 HTTP client 超时返回的 err 已经 wrap 了 context.DeadlineExceeded
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("loadUser id=%d: %w", id, err)
	}
	return nil
}

// --- Service 层：包装成结构化业务错误 ---

func getUser(ctx context.Context, id int) error {
	if err := loadUser(ctx, id); err != nil {
		return &BizError{Code: "USER_NOT_FOUND", HTTP: 404, Retry: false, Cause: err}
	}
	return nil
}

// --- typed nil 陷阱演示 ---

func badReturn() error {
	var e *BizError // nil
	return e       // 接口值：type=*BizError, value=nil → err != nil 恒成立
}

func goodReturn(e *BizError) error {
	if e == nil {
		return nil // 显式返回 nil 接口
	}
	return e
}

// --- recover 转 error：HTTP 中间件兜底，必须配合命名返回值 ---

func safeCall(fn func() error) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic recovered: %v\n%s", r, debug.Stack())
		}
	}()
	return fn()
}

// --- HTTP Handler 边界层：Is/As 分类翻译 ---

func handle(w http.ResponseWriter, r *http.Request) {
	err := getUser(r.Context(), -1)
	if err == nil {
		w.WriteHeader(http.StatusOK)
		return
	}

	var be *BizError
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		http.Error(w, "upstream timeout", http.StatusGatewayTimeout) // 504
	case errors.Is(err, context.Canceled):
		w.WriteHeader(499) // 客户端断开，不需要返回 body
	case errors.As(err, &be):
		http.Error(w, be.Code, be.HTTP) // 404 + USER_NOT_FOUND
	default:
		http.Error(w, "internal error", http.StatusInternalServerError) // 500，记录 err 但不泄露
	}
}

func main() {
	// typed nil 演示
	fmt.Println("badReturn == nil?", badReturn() == nil)    // false
	fmt.Println("goodReturn == nil?", goodReturn(nil) == nil) // true

	// 边界翻译演示
	handle(nil, nil) // 仅为编译通过；生产中用 http.ListenAndServe
}
